pluginManagement {
    repositories {
        gradlePluginPortal()
        mavenCentral()
    }
}

dependencyResolutionManagement {
    repositories {
        mavenCentral()
        google()
    }

    versionCatalogs {
        create("libs") {
            // Share versions with the plugin build, so golden files are generated by the same Kobweb version that tests
            // run against
            from(files("../../../../../../gradle/libs.versions.toml"))
            plugin("kotlin-multiplatform", "org.jetbrains.kotlin.multiplatform").versionRef("kotlin")
            plugin("kobweb-worker", "com.varabyte.kobweb.worker").versionRef("kobweb")
        }
    }
}

rootProject.name = "worker-golden-generator"

// Every test case is a worker module of its own
file("../cases").listFiles()!!.filter { it.isDirectory }.sorted().forEach { caseDir ->
    include(":${caseDir.name}")
    project(":${caseDir.name}").projectDir = caseDir
}
